import os
import sys
import hashlib
import json
import logging
from datetime import datetime

LOG_FILE = "kvstore.log"
STORE_DIR = "kvstore"

def compute_tag(data_bytes, key):
    return hashlib.sha256(data_bytes + key.encode()).digest()

def save(key):
    if not os.path.exists(STORE_DIR):
        os.makedirs(STORE_DIR)
    try:
        data = json.loads(sys.stdin.read())
        serialized = json.dumps(data).encode()
        tag = compute_tag(serialized, os.getenv("KVSTORE_KEY", ""))
        with open(os.path.join(STORE_DIR, key), "wb") as f:
            f.write(tag + serialized)
        return True
    except Exception as e:
        return False

def load(key):
    try:
        if not os.path.exists(os.path.join(STORE_DIR, key)):
            return None
        with open(os.path.join(STORE_DIR, key), "rb") as f:
            tag_bytes, serialized = f.read(16), f.read()
        if not serialized:
            return None
        try:
            data = json.loads(serialized.decode())
            computed_tag = compute_tag(serialized, os.getenv("KVSTORE_KEY", ""))
            if tag_bytes != computed_tag:
                return None
            return data
        except json.JSONDecodeError:
            return None
    except Exception:
        return None

def log_entry(command, key, status):
    timestamp = datetime.utcnow().isoformat()
    with open(LOG_FILE, "a") as f:
        f.write(f"{timestamp} {command} {key} {status}\n")

def main():
    if len(sys.argv) != 3 or sys.argv[1] not in ("save", "load"):
        print("Usage: python kvstore.py [save|load] KEY", file=sys.stderr)
        sys.exit(1)

    command = sys.argv[1]
    key = sys.argv[2]

    if command == "save":
        if not save(key):
            log_entry("save", key, "error")
            sys.exit(1)
        log_entry("save", key, "ok")
        sys.exit(0)
    elif command == "load":
        data = load(key)
        if data is None:
            log_entry("load", key, "error")
            sys.exit(1)
        print(json.dumps(data))
        log_entry("load", key, "ok")

if __name__ == "__main__":
    main()
